"""Check that each retire candidate holds nothing the canonical home lacks.

Prints file names and counts only. Never prints file contents.
"""
import hashlib
import sqlite3
from pathlib import Path

HOME = Path.home()
GD = HOME / "Library/CloudStorage/GoogleDrive-eric.rash11@gmail.com/My Drive/00_Primary_Storage_Drive"
OD = HOME / "Library/CloudStorage/OneDrive-BaylorUniversity/00_Primary_Storage_Drive/_MIGRATED_to_GoogleDrive"
DEV_DB_REPO = HOME / "DEV/DataBase_GPS_Reporting"

PAIRS = [
    ("GD _ACTIVE DataBase_GPS_Reporting", GD / "01_PROJECTS/_ACTIVE/2026-03-10_DataBase_GPS_Reporting", DEV_DB_REPO),
    ("OD migrated DataBase_GPS_Reporting", OD / "01_PROJECTS/_ACTIVE/2026-03-10_DataBase_GPS_Reporting", DEV_DB_REPO),
    ("OD migrated Football FA2026", OD / "02_SPORTS/Football/FA2026", GD / "02_SPORTS/Football/FA2026"),
]
SKIP_PARTS = {".git", "__pycache__", ".venv", "venv", "node_modules"}
SKIP_NAMES = {".DS_Store", "Thumbs.db", "desktop.ini", "Icon\r"}


def sha(p: Path) -> str:
    h = hashlib.sha256()
    with p.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def files(root: Path):
    for p in root.rglob("*"):
        if p.is_file() and not (SKIP_PARTS & set(p.relative_to(root).parts)) and p.name not in SKIP_NAMES:
            yield p


def index_by_name_hash(root: Path):
    """Canonical content index: sha -> relpaths (so a moved/renamed file still counts)."""
    by_hash = {}
    for p in files(root):
        by_hash.setdefault((p.stat().st_size, None), []).append(p)
    return by_hash


for label, cand, canon in PAIRS:
    print(f"\n=== {label}\n  candidate: {cand}\n  canonical: {canon}")
    if not cand.exists():
        print("  candidate missing")
        continue
    canon_files = list(files(canon))
    by_size = {}
    for p in canon_files:
        by_size.setdefault(p.stat().st_size, []).append(p)
    hash_cache = {}
    same_path = moved = changed = missing = 0
    problems = []
    total_bytes = 0
    for p in files(cand):
        rel = p.relative_to(cand)
        size = p.stat().st_size
        total_bytes += size
        h = sha(p)
        twin = canon / rel
        if twin.is_file() and twin.stat().st_size == size and sha(twin) == h:
            same_path += 1
            continue
        found = False
        for q in by_size.get(size, []):
            if q not in hash_cache:
                hash_cache[q] = sha(q)
            if hash_cache[q] == h:
                found = True
                break
        if found:
            moved += 1
        elif twin.is_file():
            changed += 1
            problems.append(f"DIFFERS  {rel}  (cand {size} B, canon {twin.stat().st_size} B, cand mtime {p.stat().st_mtime:.0f} vs canon {twin.stat().st_mtime:.0f})")
        else:
            missing += 1
            problems.append(f"ONLY-HERE {rel}  ({size} B)")
    print(f"  files={same_path + moved + changed + missing} bytes={total_bytes} identical_same_path={same_path} identical_elsewhere={moved} differs={changed} only_here={missing}")
    for line in problems[:60]:
        print("   ", line)
    if len(problems) > 60:
        print(f"    ... {len(problems) - 60} more")

cli_db = HOME / ".local/share/catapult-openfield-connect-pp-cli/data.db"
print(f"\n=== CLI store {cli_db}")
try:
    con = sqlite3.connect(f"file:{cli_db}?mode=ro&immutable=1", uri=True)
    tables = [r[0] for r in con.execute("select name from sqlite_master where type='table'")]
    counts = {t: con.execute(f'select count(*) from "{t}"').fetchone()[0] for t in tables}
    print("  ", counts, "nonzero:", {k: v for k, v in counts.items() if v})
except Exception as e:  # noqa: BLE001
    print("  error:", type(e).__name__, e)

