"""Metadata-first compare that never forces a cloud download.

A file counts as safely on Google Drive / DEV when the canonical side has the same
relative path and size, or the same file name and size elsewhere. Files that are local on
both sides are also compared by sha-256. Online-only ("dataless") files are never read.
Prints names and counts only.
"""
import hashlib
import os
import stat
from pathlib import Path

HOME = Path.home()
GD = HOME / "Library/CloudStorage/GoogleDrive-eric.rash11@gmail.com/My Drive/00_Primary_Storage_Drive"
OD = HOME / "Library/CloudStorage/OneDrive-BaylorUniversity/00_Primary_Storage_Drive/_MIGRATED_to_GoogleDrive"
DEV_DB_REPO = HOME / "DEV/DataBase_GPS_Reporting"
SF_DATALESS = getattr(stat, "SF_DATALESS", 0x40000000)

PAIRS = [
    ("GD _ACTIVE DataBase_GPS_Reporting", GD / "01_PROJECTS/_ACTIVE/2026-03-10_DataBase_GPS_Reporting", DEV_DB_REPO),
    ("OD migrated DataBase_GPS_Reporting", OD / "01_PROJECTS/_ACTIVE/2026-03-10_DataBase_GPS_Reporting", DEV_DB_REPO),
    ("OD migrated Football FA2026", OD / "02_SPORTS/Football/FA2026", GD / "02_SPORTS/Football/FA2026"),
]
SKIP_PARTS = {".git", "__pycache__", ".venv", "venv", "node_modules"}
SKIP_NAMES = {".DS_Store", "Thumbs.db", "desktop.ini", "Icon\r"}


def walk(root: Path):
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in SKIP_PARTS]
        for n in filenames:
            if n in SKIP_NAMES or n.startswith("~$"):
                continue
            p = Path(dirpath) / n
            st = os.lstat(p)
            if not stat.S_ISREG(st.st_mode):
                continue
            yield p, st.st_size, bool(st.st_flags & SF_DATALESS)


def sha(p: Path) -> str:
    h = hashlib.sha256()
    with p.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


for label, cand, canon in PAIRS:
    print(f"\n=== {label}")
    by_rel, by_name_size = {}, {}
    for p, size, dl in walk(canon):
        by_rel[p.relative_to(canon).as_posix()] = (p, size, dl)
        by_name_size.setdefault((p.name, size), []).append(p)
    n = matched_path = matched_elsewhere = hash_differs = 0
    unproven = []
    for p, size, dl in walk(cand):
        n += 1
        rel = p.relative_to(cand).as_posix()
        twin = by_rel.get(rel)
        if twin and twin[1] == size:
            if not dl and not twin[2] and sha(p) != sha(twin[0]):
                hash_differs += 1
                unproven.append(f"SAME-SIZE-DIFFERENT-BYTES {rel}")
            else:
                matched_path += 1
            continue
        if (p.name, size) in by_name_size:
            matched_elsewhere += 1
            continue
        why = "size differs from canonical" if twin else "not in canonical"
        unproven.append(f"{'online-only' if dl else 'local'} {size} B  {rel}  ({why})")
    print(f"  files={n} same_path_size={matched_path} same_name_size_elsewhere={matched_elsewhere} unproven={len(unproven)}")
    for line in unproven[:80]:
        print("   ", line)
    if len(unproven) > 80:
        print(f"    ... {len(unproven) - 80} more")

