def ts(local: str) -> int:
    """Unix seconds for a 'YYYY-MM-DD HH:MM' wall-clock time in America/Chicago."""
    return int(datetime.strptime(local, "%Y-%m-%d %H:%M").replace(tzinfo=ZoneInfo(TZ)).timestamp())


def activity(aid, name, local_start, minutes=120):
    start = ts(local_start)
    return {"id": aid, "name": name, "start_time": start, "end_time": start + minutes * 60}


def stat_row(athlete_id, distance=5000.0):
    return {
        "athlete_id": athlete_id,
        "total_distance": distance,
        "average_player_load": 400.0,
        "max_vel": 20.0,
        "player_load_per_minute": 5.0,
        "total_duration": 5400.0,
    }


class FakeClient:
    """Stands in for CatapultClient. list_activities returns every activity on every call,
    which exercises de-duplication and out-of-window filtering."""

    def __init__(self, activities=(), stats=None, athletes=None, roster_error=None,
                 fail_list_calls=()):
        self.activities = list(activities)
        self.stats = dict(stats or {})
        self.athletes = athletes
        self.roster_error = roster_error
        self.fail_list_calls = set(fail_list_calls)
        self.list_calls = []
        self.stats_calls = []

    def list_activities(self, start_time, end_time):
        from src.api_client import CatapultAPIError
        self.list_calls.append((int(start_time), int(end_time)))
        if len(self.list_calls) in self.fail_list_calls:
            raise CatapultAPIError(0, "network error: simulated")
        return [dict(a) for a in self.activities]

    def list_athletes(self):
        if self.roster_error:
            raise self.roster_error
        if self.athletes is None:
            ids = sorted({r["athlete_id"] for rows in self.stats.values()
                          if isinstance(rows, list) for r in rows if r.get("athlete_id")})
            return [{"id": i, "first_name": "Test", "last_name": i, "position_name": "WR"} for i in ids]
        return self.athletes

    def get_athlete_stats(self, activity_id):
        self.stats_calls.append(activity_id)
        value = self.stats.get(activity_id, [])
        if isinstance(value, Exception):
            raise value
        return [dict(r) for r in value]


