def _get(self, path: str, params: dict | None = None, retries: int = 4) -> dict:
    """GET request with exponential backoff on 429 / 5xx and network errors."""
    url = self.base_url + path
    headers = {"Authorization": f"Bearer {self._token}"}
    return self._request_with_retries(
        path, lambda: requests.get(url, headers=headers, params=params, timeout=30), retries
    )

def _post(self, path: str, body: dict, retries: int = 4) -> Any:
    """POST request with exponential backoff on 429 / 5xx and network errors."""
    url = self.base_url + path
    headers = {
        "Authorization": f"Bearer {self._token}",
        "Content-Type": "application/json",
        "Accept": "application/json",
    }
    return self._request_with_retries(
        path, lambda: requests.post(url, headers=headers, json=body, timeout=60), retries
    )

def _request_with_retries(self, path: str, send, retries: int) -> Any:
    """Send, retrying rate limits, 502/503, network errors and unreadable JSON.

    Network errors and invalid JSON surface as CatapultAPIError(0, ...), never a raw
    traceback, so callers handle every API failure the same way.
    """
    delay = 2
    last_problem: str | None = None
    for attempt in range(retries):
        try:
            resp = send()
        except requests.RequestException as e:
            last_problem = f"network error: {e}"
            logger.warning("Network error on %s: %s. Retrying in %ds (attempt %d/%d).",
                           path, e, delay, attempt + 1, retries)
            time.sleep(delay)
            delay *= 2
            continue
        if resp.status_code == 200:
            try:
                return resp.json()
            except ValueError as e:
                last_problem = f"invalid JSON: {e}"
                logger.warning("Invalid JSON from %s: %s. Retrying in %ds (attempt %d/%d).",
                               path, e, delay, attempt + 1, retries)
                time.sleep(delay)
