def _request_with_retries(self, path: str, send, retries: int) -> Any:
    """Send, retrying rate limits, 502/503, network errors and unreadable JSON.

    Network errors and invalid JSON surface as CatapultAPIError(0, ...), never a raw
    traceback, so callers handle every API failure the same way.
    """
    delay = 2
    last_problem: str | None = None
    for attempt in range(retries):
        try:
            resp = send()
        except requests.RequestException as e:
            last_problem = f"network error: {e}"
            logger.warning("Network error on %s: %s. Retrying in %ds (attempt %d/%d).",
                           path, e, delay, attempt + 1, retries)
            time.sleep(delay)
            delay *= 2
            continue
        if resp.status_code == 200:
            try:
                return resp.json()
            except ValueError as e:
                last_problem = f"invalid JSON: {e}"
                logger.warning("Invalid JSON from %s: %s. Retrying in %ds (attempt %d/%d).",
                               path, e, delay, attempt + 1, retries)
                time.sleep(delay)
                delay *= 2
                continue
        if resp.status_code in (429, 503, 502):
            last_problem = None
            logger.warning(
                "Rate limit / server error %d on %s. Retrying in %ds (attempt %d/%d).",
                resp.status_code, path, delay, attempt + 1, retries,
            )
            time.sleep(delay)
            delay *= 2
            continue
        raise CatapultAPIError(resp.status_code, resp.text)
