        except duckdb.Error as e:
            raise ImportExit(2, f"cannot read database {args.db}: {e}")
        if newest is None:
            raise ImportExit(1, "--since-db: database has no sessions; run once with --start")
        start_date = pull.since_db_start(newest, overlap)
        end_date = today
    else:
        state["mode"] = "range"
        start_date = _parse_date(args.start or DEFAULT_START, "--start")
        end_date = _parse_date(args.end, "--end") if args.end else today
    if args.dry_run:
        state["mode"] = "dry-run"

    if start_date > end_date:
        raise ImportExit(1, f"--start ({start_date}) is after --end ({end_date})")
    state["window_start"] = start_date.isoformat()
    state["window_end"] = end_date.isoformat()

    print(f"\nBulk import: {start_date} to {end_date}")
