def next_retry_from(state: dict, code: int, previous: dict | None) -> str | None:
    """Earliest date the next --since-db run must re-cover (None when nothing is pending).

    A since-db run always starts at or before the previous retry_from, so when it finishes
    ok/partial its own failures are the complete pending set. Other runs never clear an
    earlier value; they can only lower it. An unexpected crash mid-run re-covers its window.
    """
    prev = _iso_date_or_none((previous or {}).get("retry_from"))
    fails = sorted(state.get("_failure_dates") or ())
    own = date.fromisoformat(fails[0]) if fails else None
    mode = state.get("mode")
    if mode in (None, "dry-run"):
        best = prev
    elif mode == "since-db" and code in (0, 3):
        best = own
    else:
        candidates = [d for d in (prev, own) if d]
        if code == 5 and state.get("window_start"):
            candidates.append(date.fromisoformat(state["window_start"]))
        best = min(candidates) if candidates else None
    return best.isoformat() if best else None


