def _write_pending_receipt(path: str, state: dict, previous: dict | None, start_date: date) -> None:
    """Write a status=running receipt whose retry_from covers this run's whole window.

    If the final receipt write later fails (disk full, permissions), this one stays on disk,
    so the next --since-db run still re-covers anything this run left unimported. If this
    write fails, nothing is imported.
    """
    prev = _iso_date_or_none((previous or {}).get("retry_from"))
    retry = min(d for d in (prev, start_date) if d)
    pending = {k: v for k, v in state.items() if k != "_failure_dates"}
    pending.update(status="running", exit_code=None, finished_at=None, retry_from=retry.isoformat())
    try:
        pull.write_receipt(path, pending, previous)
    except OSError as e:
        raise ImportExit(5, f"cannot write the pending receipt {path}: {e}; nothing imported")


